        # Transform to rotated coordinate space for non-separability
        y_rotated = np.dot(np.asarray([x_vector]), self.rotation_matrix.T).flatten()

        # Calculate Voronoi cell centers in rotated space
        cell_centers = []
        for i in range(-5, 6):
            for j in range(-5, 6):
