import numpy as np

class OrthogonalFractalHarmonicField:
    def __init__(self, dim):
        self.dim = dim
        # Precompute orthogonal transformation matrix (Hadamard-like)
        self.rotation_matrix = np.eye(dim)  # Identity for simplicity; can be replaced with Householder/Hadamard
        # Fractal parameters
        self.max_iter = 10  # Controls fractal depth
        self.scale_factor = 2.5  # Scales the fractal pattern to fit [-5,5]^d

    def f(self, x):
        """
        Evaluate the OrthogonalFractalHarmonicField function.
        Args:
            x: numpy array of shape (dim,) representing the input point
        Returns:
            float: function value at x
        """
        # Apply orthogonal transformation for non-separability
        x_rot = np.dot(x, self.rotation_matrix)

        # Center the domain to [-5,5]^d
        x_centered = x_rot / 5.0

        # Fractal harmonic potential construction
        def fractal_harmonic(z, iter):
            if iter >= self.max_iter:
                return np.sum(np.cos(2 * np.pi * z) ** 2)
            else:
                # Recursive subdivision with fractal pattern
                z_scaled = z * self.scale_factor
                mask = (np.abs(z_scaled) < 1.0).all()
                if mask:
                    return fractal_harmonic(z_scaled, iter + 1)
                else:
                    return np.sum(np.cos(2 * np.pi * z) ** 2)

        # Evaluate the fractal harmonic function
        value = fractal_harmonic(x_centered, 0)

        # Add global harmonic modulation for smoothness
        global_modulation = 0.1 * np.sum(np.sin(2 * np.pi * x_centered))

        return value + global_modulation

    def get_global_minimum(self):
        """Returns the known global minimum location and value."""
        return (np.zeros(self.dim), 0.0)
